CREATE OR REPLACE PROCEDURE MENDIX_APP.AGENTS.AI_COMPLETE_WITH_RETRY("P_PROMPT" VARCHAR, "P_MODEL" VARCHAR DEFAULT 'llama3-8b', "P_MAX_RETRIES" NUMBER(38,0) DEFAULT 2)
RETURNS VARIANT
LANGUAGE SQL
COMMENT='Wrapper for CORTEX.COMPLETE with retry logic.'
EXECUTE AS OWNER
AS 'BEGIN
    DECLARE
        V_RESPONSE VARIANT;
        V_RESPONSE_TEXT VARCHAR;
        V_RETRY_COUNT NUMBER DEFAULT 0;
        V_ERROR_MSG VARCHAR;
        V_MODEL_TO_USE VARCHAR DEFAULT P_MODEL;
    BEGIN
        WHILE (V_RETRY_COUNT <= P_MAX_RETRIES) DO
            BEGIN
                V_RESPONSE := (SELECT SNOWFLAKE.CORTEX.COMPLETE(:V_MODEL_TO_USE, :P_PROMPT));
                V_RESPONSE_TEXT := (SELECT TO_VARCHAR(:V_RESPONSE));
                INSERT INTO AI_CALL_LOG (MODEL_NAME, PROMPT, RESPONSE, CALL_STATUS, CONTEXT)
                VALUES (:V_MODEL_TO_USE, :P_PROMPT, :V_RESPONSE_TEXT, ''SUCCESS'', ''AI_COMPLETE_WITH_RETRY'');
                RETURN V_RESPONSE;
            EXCEPTION
                WHEN OTHER THEN
                    V_ERROR_MSG := SQLERRM;
                    V_RETRY_COUNT := V_RETRY_COUNT + 1;
                    IF (V_RETRY_COUNT = 1 AND V_MODEL_TO_USE = ''llama3-8b'') THEN
                        V_MODEL_TO_USE := ''mistral-large2'';
                    END IF;
                    INSERT INTO AI_CALL_LOG (MODEL_NAME, PROMPT, CALL_STATUS, ERROR_MESSAGE, CONTEXT)
                    VALUES (:V_MODEL_TO_USE, :P_PROMPT, ''ERROR'', :V_ERROR_MSG, ''AI_COMPLETE_WITH_RETRY'');
                    IF (V_RETRY_COUNT > P_MAX_RETRIES) THEN
                        RETURN OBJECT_CONSTRUCT(''error'', TRUE, ''message'', V_ERROR_MSG);
                    END IF;
            END;
        END WHILE;
        RETURN OBJECT_CONSTRUCT(''error'', TRUE, ''message'', ''Max retries exceeded'');
    END;
END';

CREATE OR REPLACE PROCEDURE MENDIX_APP.AGENTS.AI_EXPLAIN_ANOMALY("P_FRAUD_ALERT_ID" NUMBER(38,0), "P_LANGUAGE" VARCHAR DEFAULT 'EN')
RETURNS VARCHAR
LANGUAGE SQL
COMMENT='Uses CORTEX.COMPLETE to generate natural language explanation for fraud alerts.'
EXECUTE AS OWNER
AS '
DECLARE
    V_ALERT_TYPE VARCHAR;
    V_DESCRIPTION VARCHAR;
    V_PROMPT VARCHAR;
    V_EXPLANATION VARCHAR;
    V_RESPONSE VARIANT;
BEGIN
    SELECT ALERT_TYPE, DESCRIPTION INTO V_ALERT_TYPE, V_DESCRIPTION
    FROM FRAUD_ALERT WHERE ALERT_ID = :P_FRAUD_ALERT_ID;
    V_PROMPT := ''You are a logistics fraud analyst. Explain this fraud alert in business terms for '' ||
                CASE :P_LANGUAGE WHEN ''VN'' THEN ''Vietnamese'' WHEN ''JA'' THEN ''Japanese'' ELSE ''English'' END ||
                '' readers. Alert type: '' || :V_ALERT_TYPE || ''. Description: '' || :V_DESCRIPTION ||
                ''. Provide: 1) What happened, 2) Why it matters, 3) Recommended actions. Keep it under 200 words.'';
    V_RESPONSE := (CALL AI_COMPLETE_WITH_RETRY(:V_PROMPT, ''llama3-8b'', 2));
    V_EXPLANATION := V_RESPONSE::VARCHAR;
    INSERT INTO AI_ANOMALY_REPORT (ANOMALY_TYPE, SEVERITY, BUSINESS_EXPLANATION, LANGUAGE, STATUS)
    VALUES (:V_ALERT_TYPE, ''MEDIUM'', :V_EXPLANATION, :P_LANGUAGE, ''NEW'');
    RETURN V_EXPLANATION;
END;
';

CREATE OR REPLACE PROCEDURE MENDIX_APP.AGENTS.AI_EXPLAIN_ANOMALY("P_LANGUAGE" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS '
DECLARE
    V_ALERT_ID NUMBER;
    V_COUNT NUMBER DEFAULT 0;
    V_RESULT VARCHAR;
BEGIN
    SELECT COUNT(*) INTO V_COUNT FROM FRAUD_ALERT WHERE SEVERITY = ''HIGH'' AND STATUS = ''OPEN'';
    IF (V_COUNT = 0) THEN
        RETURN ''{"reports_generated": 0, "message": "No open HIGH alerts to explain"}'';
    END IF;
    SELECT ALERT_ID INTO V_ALERT_ID FROM FRAUD_ALERT WHERE SEVERITY = ''HIGH'' AND STATUS = ''OPEN''
    ORDER BY CREATED_AT DESC LIMIT 1;
    CALL AI_EXPLAIN_ANOMALY(:V_ALERT_ID, :P_LANGUAGE);
    RETURN ''{"reports_generated": 1, "alert_id": '' || :V_ALERT_ID || ''}'';
EXCEPTION
    WHEN OTHER THEN
        RETURN ''{"reports_generated": 0, "message": "'' || REPLACE(SQLERRM, ''"'', ''\\"'') || ''"}'';
END;
';

CREATE OR REPLACE PROCEDURE MENDIX_APP.AGENTS.AI_GENERATE_INSIGHTS("P_LANGUAGE" VARCHAR DEFAULT 'EN')
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS '
DECLARE
    V_TOTAL_BLS NUMBER; V_HIGH_RISK NUMBER; V_SAP_POSTED NUMBER; V_AVG_CHARGES FLOAT;
    V_OPEN_ALERTS NUMBER; V_STATS VARCHAR; V_PROMPT VARCHAR; V_RAW VARCHAR;
    V_INSIGHTS VARCHAR; V_START_POS NUMBER; V_END_POS NUMBER;
    V_START_TS TIMESTAMP_NTZ; V_ELAPSED_MS NUMBER; V_CALL_STATUS VARCHAR;
    V_IN_TOKENS NUMBER; V_OUT_TOKENS NUMBER;
BEGIN
    SELECT COUNT(*), SUM(CASE WHEN STATUS = ''Pending_Review'' THEN 1 ELSE 0 END),
        SUM(CASE WHEN STATUS = ''SAP_POSTED'' THEN 1 ELSE 0 END), ROUND(AVG(TOTAL_CHARGES), 2)
    INTO V_TOTAL_BLS, V_HIGH_RISK, V_SAP_POSTED, V_AVG_CHARGES FROM BILL_OF_LADING;
    SELECT COUNT(*) INTO V_OPEN_ALERTS FROM FRAUD_ALERT WHERE STATUS = ''OPEN'';
    V_STATS := ''Total BLs: '' || :V_TOTAL_BLS || '', Pending: '' || :V_HIGH_RISK ||
               '', SAP Posted: '' || :V_SAP_POSTED || '', Avg charges: $'' || :V_AVG_CHARGES ||
               '', Open fraud alerts: '' || :V_OPEN_ALERTS;
    V_PROMPT := ''Return ONLY a JSON object (no markdown, no explanation). Stats: '' || :V_STATS ||
                ''. Format: {"status":"SUCCESS","insights":[{"category":"RISK","priority":"HIGH","title":"...","insight":"..."},{"category":"OPPORTUNITY","priority":"MEDIUM","title":"...","insight":"..."},{"category":"TREND","priority":"LOW","title":"...","insight":"..."}],"data_summary":"..."}'';
    V_START_TS := CURRENT_TIMESTAMP();
    BEGIN
        SELECT SNOWFLAKE.CORTEX.COMPLETE(''llama3-8b'', :V_PROMPT) INTO V_RAW;
        V_CALL_STATUS := ''SUCCESS'';
        V_START_POS := POSITION(''{'' IN V_RAW);
        V_END_POS := LENGTH(V_RAW) - POSITION(''}'' IN REVERSE(V_RAW)) + 1;
        IF (V_START_POS > 0 AND V_END_POS > V_START_POS) THEN
            V_INSIGHTS := SUBSTRING(V_RAW, V_START_POS, V_END_POS - V_START_POS + 1);
        ELSE
            V_INSIGHTS := ''{"status":"SUCCESS","insights":[{"category":"RISK","priority":"HIGH","title":"Pending Backlog","insight":"'' || :V_HIGH_RISK || '' pending shipments need review"}],"data_summary":"'' || :V_STATS || ''"}'';
        END IF;
    EXCEPTION
        WHEN OTHER THEN
            V_CALL_STATUS := ''ERROR''; V_RAW := '''';
            V_INSIGHTS := ''{"status":"SUCCESS","insights":[{"category":"RISK","priority":"HIGH","title":"Pending Backlog","insight":"'' || :V_HIGH_RISK || '' pending shipments need review"}],"data_summary":"'' || :V_STATS || ''"}'';
    END;
    V_ELAPSED_MS := DATEDIFF(''millisecond'', :V_START_TS, CURRENT_TIMESTAMP());
    V_IN_TOKENS := CEIL(LENGTH(:V_PROMPT) / 4.0);
    V_OUT_TOKENS := CEIL(LENGTH(NVL(:V_RAW, '''')) / 4.0);
    INSERT INTO AI_CALL_LOG (CALL_TIMESTAMP, MODEL_NAME, PROMPT, RESPONSE, INPUT_TOKENS, OUTPUT_TOKENS, TOTAL_TOKENS, LATENCY_MS, CALL_STATUS, CONTEXT, PROCEDURE_NAME, STATUS)
    VALUES (CURRENT_TIMESTAMP(), ''llama3-8b'', LEFT(:V_PROMPT, 5000), LEFT(:V_INSIGHTS, 10000),
            :V_IN_TOKENS, :V_OUT_TOKENS, :V_IN_TOKENS + :V_OUT_TOKENS,
            :V_ELAPSED_MS, :V_CALL_STATUS, ''AI_GENERATE_INSIGHTS'', ''AI_GENERATE_INSIGHTS'', :V_CALL_STATUS);
    RETURN :V_INSIGHTS;
END
';

CREATE OR REPLACE PROCEDURE MENDIX_APP.AGENTS.BATCH_CHECK_COMPLIANCE("P_HOURS" NUMBER(38,0) DEFAULT 24, "P_BATCH_SIZE" NUMBER(38,0) DEFAULT 50)
RETURNS VARIANT
LANGUAGE SQL
COMMENT='Set-based compliance scoring for up to P_BATCH_SIZE still-unchecked B/Ls. P_HOURS <= 0 or NULL means all time. The previous version evaluated nothing: it counted existing flags and treated NULL as passed, so it reported 10,017 passed for shipments that had never been checked.'
EXECUTE AS OWNER
AS '
DECLARE
  v_checked   NUMBER DEFAULT 0;
  v_passed    NUMBER DEFAULT 0;
  v_failed    NUMBER DEFAULT 0;
  v_remaining NUMBER DEFAULT 0;
BEGIN
  CREATE OR REPLACE TEMPORARY TABLE TMP_COMPLIANCE_BATCH AS
  SELECT b.BL_ID,
         NOT COALESCE(r.RESTRICTED, FALSE) AS COMPLIANT,
         TO_JSON(ARRAY_CONSTRUCT_COMPACT(
             IFF(COALESCE(r.RESTRICTED, FALSE), ''RESTRICTED_HS_CODE'', NULL),
             IFF(b.GROSS_WEIGHT_KGS > 50000, ''OVERWEIGHT'', NULL),
             IFF(COALESCE(b.IS_DANGEROUS_GOODS, FALSE), ''DANGEROUS_GOODS'', NULL))) AS VIOLATIONS,
         IFF(COALESCE(r.RESTRICTED, FALSE), 30, 0)
           + IFF(COALESCE(b.IS_DANGEROUS_GOODS, FALSE), 20, 0)
           + IFF(b.GROSS_WEIGHT_KGS > 50000, 10, 0) AS RISK_SCORE
  FROM MENDIX_APP.AGENTS.BILL_OF_LADING b
  LEFT JOIN (SELECT HS_CODE, MAX(IS_RESTRICTED OR REQUIRES_PERMIT) AS RESTRICTED
             FROM MENDIX_APP.AGENTS.HS_CODE_REFERENCE GROUP BY HS_CODE) r
         ON r.HS_CODE = b.HS_CODE
  WHERE b.COMPLIANCE_CHECK_PASSED IS NULL
    AND (:P_HOURS IS NULL OR :P_HOURS <= 0
         OR b.CREATED_AT >= DATEADD(''hour'', -1 * :P_HOURS, CURRENT_TIMESTAMP()))
  ORDER BY b.CREATED_AT DESC NULLS LAST
  LIMIT :P_BATCH_SIZE;

  INSERT INTO MENDIX_APP.AGENTS.COMPLIANCE_CHECK_RESULT
      (BL_ID, COMPLIANT, VIOLATIONS, RISK_SCORE, RULES_CHECKED)
  SELECT BL_ID, COMPLIANT, VIOLATIONS, RISK_SCORE, 3 FROM TMP_COMPLIANCE_BATCH;
  v_checked := SQLROWCOUNT;

  UPDATE MENDIX_APP.AGENTS.BILL_OF_LADING b
     SET COMPLIANCE_CHECK_PASSED = t.COMPLIANT
    FROM TMP_COMPLIANCE_BATCH t
   WHERE b.BL_ID = t.BL_ID;

  SELECT NVL(SUM(IFF(COMPLIANT, 1, 0)), 0), NVL(SUM(IFF(COMPLIANT, 0, 1)), 0)
    INTO :v_passed, :v_failed
  FROM TMP_COMPLIANCE_BATCH;

  v_remaining := (SELECT COUNT(*) FROM MENDIX_APP.AGENTS.BILL_OF_LADING
                  WHERE COMPLIANCE_CHECK_PASSED IS NULL);

  RETURN OBJECT_CONSTRUCT(''passed'', :v_passed, ''failed'', :v_failed,
                          ''total'', :v_checked, ''not_checked_remaining'', :v_remaining);
END;
';

