CREATE OR REPLACE PROCEDURE MENDIX_APP.AGENTS.CHAT_WITH_DATA("USER_MESSAGE" VARCHAR)
RETURNS VARCHAR
LANGUAGE SQL
COMMENT='Conversational BI: classifies intent, generates SQL via AI, executes live, summarizes result.'
EXECUTE AS CALLER
AS '
DECLARE
  intent VARCHAR; generated_sql VARCHAR; clean_sql VARCHAR; wrapped_sql VARCHAR;
  result_text VARCHAR; final_answer VARCHAR;
  schema_context VARCHAR DEFAULT
    ''You must ALWAYS use fully-qualified table names in the exact form MENDIX_APP.AGENTS.<TABLE_NAME>. Available tables:'' || chr(10) ||
    ''- MENDIX_APP.AGENTS.BILL_OF_LADING (shipments): BL_ID, BL_NUMBER, SHIPPER_NAME, CONSIGNEE_NAME, PORT_OF_LOADING_LOCODE, PORT_OF_DISCHARGE_LOCODE, VESSEL_NAME, CARRIER_NAME, HS_CODE, GROSS_WEIGHT_KGS, VOLUME_CBM, TOTAL_CHARGES, FREIGHT_AMOUNT, STATUS, IS_DANGEROUS_GOODS, COMPLIANCE_CHECK_PASSED, FRAUD_CHECK_PASSED, BL_DATE, ETD, ETA'' || chr(10) ||
    ''- MENDIX_APP.AGENTS.PORT_MASTER (seaports): PORT_CODE, PORT_NAME, COUNTRY, COUNTRY_CODE, PORT_TYPE, IS_ACTIVE'' || chr(10) ||
    ''- MENDIX_APP.AGENTS.VESSEL_REGISTRY: VESSEL_NAME, IMO_NUMBER, FLAG, GROSS_TONNAGE, VESSEL_TYPE, OPERATOR_NAME, IS_ACTIVE'' || chr(10) ||
    ''- MENDIX_APP.AGENTS.HS_CODE_REFERENCE: HS_CODE, DESCRIPTION, CATEGORY, IS_DANGEROUS_GOODS, IS_RESTRICTED'' || chr(10) ||
    ''- MENDIX_APP.AGENTS.FRAUD_ALERT: ALERT_ID, BL_ID, ALERT_TYPE, SEVERITY, STATUS, DESCRIPTION, DETECTED_AT'' || chr(10) ||
    ''Write PLAIN standard SQL only (SELECT/JOIN/WHERE/GROUP BY/ORDER BY), every table reference fully qualified. NOTE: country/port question ambiguous between PORT_OF_LOADING (origin) and PORT_OF_DISCHARGE (destination) - prefer PORT_OF_DISCHARGE as default.'';
BEGIN
  SELECT SNOWFLAKE.CORTEX.COMPLETE(''mistral-large2'',
    ''Classify this message as either DATA_QUERY or CONVERSATION. DATA_QUERY: asks about shipments, carriers, ports, vessels, revenue, status, routes, statistics. CONVERSATION: greetings, thanks, general chat. Reply ONLY the word.'' || chr(10) || ''Message: '' || :user_message
  ) INTO :intent;
  intent := TRIM(intent);
  IF (intent LIKE ''%CONVERSATION%'') THEN
    SELECT SNOWFLAKE.CORTEX.COMPLETE(''mistral-large2'',
      ''You are VF Logistics AI Assistant. Be helpful, friendly, professional. Respond in same language as user. Never provide DELETE/DROP/TRUNCATE/UPDATE SQL. IMPORTANT: if your main answer is NOT in English, append a short English translation on a new line prefixed with "[EN]: ".'' || chr(10) || ''User: '' || :user_message
    ) INTO :final_answer;
    RETURN final_answer;
  END IF;
  SELECT SNOWFLAKE.CORTEX.COMPLETE(''mistral-large2'',
    ''You are a Snowflake SQL generator. Write ONE single read-only SQL statement. Return ONLY the raw SQL: no markdown, no backticks, no explanation, no trailing semicolon. Must start with SELECT or WITH. If modify/delete requested, write: SELECT ''''REFUSED'''' AS refused.'' || chr(10) || :schema_context || chr(10) || ''Question: '' || :user_message
  ) INTO :generated_sql;
  clean_sql := TRIM(generated_sql);
  clean_sql := REGEXP_REPLACE(clean_sql, ''^```sql|^```|```$'', '''');
  clean_sql := REGEXP_REPLACE(clean_sql, '';\\s*$'', '''');
  clean_sql := TRIM(clean_sql);
  IF (NOT (clean_sql ILIKE ''SELECT%'' OR clean_sql ILIKE ''WITH%'')) THEN
    RETURN ''Sorry, I could not build a valid query for this question.'';
  END IF;
  IF (clean_sql ILIKE ''%INSERT %'' OR clean_sql ILIKE ''%UPDATE %'' OR clean_sql ILIKE ''%DELETE %'' OR clean_sql ILIKE ''%DROP %'' OR clean_sql ILIKE ''%ALTER %'' OR clean_sql ILIKE ''%CREATE %'' OR clean_sql ILIKE ''%MERGE %'' OR clean_sql ILIKE ''%GRANT %'' OR clean_sql ILIKE ''%TRUNCATE%'') THEN
    RETURN ''Sorry, I cannot run this query for data safety reasons.'';
  END IF;
  IF (clean_sql ILIKE ''%REFUSED%'') THEN
    RETURN ''Sorry, I cannot modify or delete data. Please contact an administrator.'';
  END IF;
  wrapped_sql := ''SELECT COALESCE(LISTAGG(TO_JSON(OBJECT_CONSTRUCT(*)), '''''' || chr(10) || ''''''), ''''(no rows returned)'''') FROM (SELECT * FROM ('' || clean_sql || '') LIMIT 30)'';
  BEGIN
    LET res RESULTSET := (EXECUTE IMMEDIATE :wrapped_sql);
    LET cur CURSOR FOR res;
    OPEN cur; FETCH cur INTO result_text; CLOSE cur;
  EXCEPTION
    WHEN OTHER THEN
      RETURN ''Sorry, I could not query this data. Could you try rephrasing your question?'';
  END;
  SELECT SNOWFLAKE.CORTEX.COMPLETE(''mistral-large2'',
    ''You are VF Logistics AI data analyst. Answer using ONLY this data, be specific with numbers, respond in the same language as the user question. If data says (no rows returned), say politely there is no data found. If your main answer is NOT in English, append English translation on new line prefixed with "[EN]: ".'' || chr(10) ||
    ''Question: '' || :user_message || chr(10) || ''SQL executed: '' || :clean_sql || chr(10) || ''Query result data: '' || :result_text
  ) INTO :final_answer;
  RETURN final_answer;
END;
';

CREATE OR REPLACE PROCEDURE MENDIX_APP.AGENTS.CHECK_AI_BUDGET()
RETURNS VARCHAR
LANGUAGE SQL
EXECUTE AS OWNER
AS '
DECLARE
    V_TODAY_COST FLOAT; V_THRESHOLD FLOAT;
BEGIN
    SELECT COALESCE(SUM(TOTAL_TOKENS * 0.0000015), 0) INTO V_TODAY_COST
    FROM AI_CALL_LOG WHERE DATE(CALL_TIMESTAMP) = CURRENT_DATE();
    SELECT CONFIG_VALUE::FLOAT INTO V_THRESHOLD FROM APP_CONFIG WHERE CONFIG_KEY = ''DAILY_COST_ALERT_USD'';
    IF (V_TODAY_COST > V_THRESHOLD) THEN
        RETURN ''{"status":"OVER_BUDGET","cost":'' || :V_TODAY_COST || '',"threshold":'' || :V_THRESHOLD || ''}'';
    ELSE
        RETURN ''{"status":"OK","cost":'' || :V_TODAY_COST || '',"threshold":'' || :V_THRESHOLD || '',"remaining":'' || (:V_THRESHOLD - :V_TODAY_COST) || ''}'';
    END IF;
END;
';
